/// 提供「清除历史」按钮
class SearchHistoryList extends StatefulWidget {
  const SearchHistoryList({
    super.key,
    required this.accessToken,
    required this.onHistorySelected,
    required this.onClearHistory,
    this.maxItems = 5,
  });

